import{getColorEnabledAsync}from"../../utils/color.js";var humanize=t=>{const[e,o]=[",","."];return t.map(t=>t.replace(/(\d)(?=(\d\d\d)+(?!\d))/g,"$1"+e)).join(o)},time=t=>{const e=Date.now()-t;return humanize([e<1e3?e+"ms":Math.round(e/1e3)+"s"])},colorStatus=async t=>{if(await getColorEnabledAsync())switch(t/100|0){case 5:return`[31m${t}[0m`;case 4:return`[33m${t}[0m`;case 3:return`[36m${t}[0m`;case 2:return`[32m${t}[0m`}return`${t}`};async function log(t,e,o,a,r=0,n){t("<--"===e?`${e} ${o} ${a}`:`${e} ${o} ${a} ${await colorStatus(r)} ${n}`)}var logger=(t=console.log)=>async function(e,o){const{method:a,url:r}=e.req,n=r.slice(r.indexOf("/",8));await log(t,"<--",a,n);const s=Date.now();await o(),await log(t,"--\x3e",a,n,e.res.status,time(s))};export{logger};